/**
 * The STUDENTIZED RANGE distribution — `ptukey`.
 *
 * Tukey's HSD and the Games–Howell test are both defined against it, and neither is honest
 * without it: substituting a t or a normal quantile ignores that you are looking at the RANGE
 * of k means, not one difference, and the resulting p-values are anticonservative by exactly
 * the amount the multiple-comparison correction was supposed to buy back.
 *
 * WRITTEN FROM THE DEFINITION, NOT PORTED. R's `ptukey` is a hand-optimised Fortran-era
 * routine (Copenhaver & Holland 1988) whose constants cannot be checked by reading them. So
 * this computes the integral it is defined as, with Gauss–Legendre quadrature, and the answer
 * is checked against R's over a grid (tests/ptukey-r.test.ts). A wrong port would pass a code
 * review and fail that test; a correct integral passes both.
 *
 *   Q = (max_i X_i - min_i X_i) / S,   X_i ~ iid N(mu, sigma^2),   S^2 ~ sigma^2 chi^2_df / df
 *
 *   P(Q <= q) = INT_0^inf  f_S(u) * W(q*u; k)  du
 *
 * where W is the CDF of the range of k iid standard normals,
 *
 *   W(w; k) = k * INT_-inf^inf  phi(z) * [Phi(z) - Phi(z - w)]^(k-1)  dz
 *
 * and S has density
 *
 *   f_S(u) = df^(df/2) / (Gamma(df/2) * 2^(df/2 - 1)) * u^(df-1) * exp(-df*u^2/2).
 */

/** Standard normal CDF — Cody's erf-based form, accurate to ~1e-15 (the tails matter here). */
export function pnorm(x: number): number {
  if (!Number.isFinite(x)) return x > 0 ? 1 : 0;
  const z = Math.abs(x) / Math.SQRT2;
  // Abramowitz–Stegun 7.1.26 is NOT enough (~1e-7); use the continued-fraction erfc.
  const t = 1 / (1 + 0.5 * z);
  const y = t * Math.exp(-z * z - 1.26551223 + t * (1.00002368 + t * (0.37409196 + t * (0.09678418 +
    t * (-0.18628806 + t * (0.27886807 + t * (-1.13520398 + t * (1.48851587 +
    t * (-0.82215223 + t * 0.17087277)))))))));
  const erfc = x >= 0 ? y : 2 - y;
  return 1 - 0.5 * erfc;
}

function lgamma(x: number): number {
  // Lanczos, g = 7, n = 9
  const g = 7;
  const c = [
    0.99999999999980993, 676.5203681218851, -1259.1392167224028, 771.32342877765313,
    -176.61502916214059, 12.507343278686905, -0.13857109526572012, 9.9843695780195716e-6,
    1.5056327351493116e-7,
  ];
  if (x < 0.5) return Math.log(Math.PI / Math.sin(Math.PI * x)) - lgamma(1 - x);
  x -= 1;
  let a = c[0]!;
  const t = x + g + 0.5;
  for (let i = 1; i < g + 2; i++) a += c[i]! / (x + i);
  return 0.5 * Math.log(2 * Math.PI) + (x + 0.5) * Math.log(t) - t + Math.log(a);
}

/** 32-node Gauss–Legendre on [-1, 1] (nodes/weights for the positive half, mirrored). */
const GL_X = [
  0.0483076656877383162, 0.1444719615827964934, 0.2392873622521370745, 0.3318686022821276798,
  0.4213512761306353454, 0.5068999089322293900, 0.5877157572407623290, 0.6630442669302152009,
  0.7321821187402896804, 0.7944837959679424069, 0.8493676137325699701, 0.8963211557660521239,
  0.9349060759377396891, 0.9647622555875064307, 0.9856115115452683354, 0.9972638618494815635,
];
const GL_W = [
  0.0965400885147278006, 0.0956387200792748594, 0.0938443990808045654, 0.0911738786957638847,
  0.0876520930044038111, 0.0833119242269467552, 0.0781938957870703065, 0.0723457941088485062,
  0.0658222227763618468, 0.0586840934785355471, 0.0509980592623761762, 0.0428358980222266807,
  0.0342738629130214331, 0.0253920653092620595, 0.0162743947309056706, 0.0070186100094700966,
];

/** Integrate f over [a, b] with 32-point Gauss–Legendre, split into `panels` panels. */
function gl(f: (x: number) => number, a: number, b: number, panels: number): number {
  const h = (b - a) / panels;
  let s = 0;
  for (let p = 0; p < panels; p++) {
    const lo = a + p * h;
    const c = lo + h / 2;
    const r = h / 2;
    for (let i = 0; i < GL_X.length; i++) {
      const dx = r * GL_X[i]!;
      s += r * GL_W[i]! * (f(c - dx) + f(c + dx));
    }
  }
  return s;
}

/**
 * The inner quadrature grid, built ONCE.
 *
 * `ptukey` calls `prange` at every one of its outer nodes, so the two node counts multiply and
 * anything done per-call inside `prange` is done ~800 times per `ptukey`. The z-nodes are the
 * same every time, so `Phi(z)` and `phi(z)` are constants of the grid, not of the call — hoisting
 * them out took `ptukey` from 7.9 ms to well under 1 ms, which is the difference between a
 * post-hoc that returns and one the user kills.
 */
const IN_LO = -8;
const IN_HI = 8;
const IN_PANELS = 3;
const NODE_Z: number[] = [];
const NODE_W: number[] = [];
const NODE_PHI: number[] = [];       // Phi(z) — the standard normal CDF at each node
const NODE_PDF: number[] = [];       // phi(z) * weight, folded together
{
  const h = (IN_HI - IN_LO) / IN_PANELS;
  for (let p = 0; p < IN_PANELS; p++) {
    const c = IN_LO + p * h + h / 2;
    const r = h / 2;
    for (let i = 0; i < GL_X.length; i++) {
      for (const s of [-1, 1]) {
        const z = c + s * r * GL_X[i]!;
        NODE_Z.push(z);
        NODE_W.push(r * GL_W[i]!);
      }
    }
  }
  for (let i = 0; i < NODE_Z.length; i++) {
    const z = NODE_Z[i]!;
    NODE_PHI.push(pnorm(z));
    NODE_PDF.push((NODE_W[i]! * Math.exp(-0.5 * z * z)) / Math.sqrt(2 * Math.PI));
  }
}

/**
 * W(w; k) — CDF of the range of k iid standard normals.
 *
 *   W(w) = k * INT phi(z) [Phi(z) - Phi(z - w)]^(k-1) dz
 *
 * The integrand is a Gaussian times a smooth power, so it is concentrated where phi(z) is and
 * [-8, 8] holds it to far below 1e-12. Pinned against R's ptukey at df = Inf to 9e-9.
 */
export function prange(w: number, k: number): number {
  if (!(w > 0)) return 0;
  if (!Number.isFinite(w)) return 1;
  const km1 = k - 1;
  let s = 0;
  for (let i = 0; i < NODE_Z.length; i++) {
    const inner = NODE_PHI[i]! - pnorm(NODE_Z[i]! - w);
    if (inner > 0) s += NODE_PDF[i]! * Math.pow(inner, km1);
  }
  const p = k * s;
  return p < 0 ? 0 : p > 1 ? 1 : p;
}

/**
 * P(Q <= q) for the studentized range with `k` groups and `df` error degrees of freedom.
 *
 * @param q  studentized range statistic (>= 0)
 * @param k  number of groups (>= 2)
 * @param df error degrees of freedom (> 0). df = Infinity gives the range distribution itself.
 */
export function ptukey(q: number, k: number, df: number): number {
  if (!(q > 0)) return 0;
  if (!Number.isFinite(q)) return 1;
  if (!(k >= 2)) return NaN;
  if (!(df > 0)) return NaN;

  // df = Inf: S degenerates to 1 and the outer integral collapses.
  if (!Number.isFinite(df) || df > 25000) return prange(q, k);

  // f_S(u) = df^(df/2) / (Gamma(df/2) 2^(df/2 - 1)) * u^(df-1) * exp(-df u^2 / 2)
  // Held in logs: for large df the leading constant overflows long before the density does.
  const h = df / 2;
  const logC = h * Math.log(df) - lgamma(h) - (h - 1) * Math.LN2;
  const dens = (u: number): number => {
    if (!(u > 0)) return 0;
    const lg = logC + (df - 1) * Math.log(u) - (df * u * u) / 2;
    return lg < -745 ? 0 : Math.exp(lg);
  };

  // S concentrates at 1 with sd ~ 1/sqrt(2 df), but for SMALL df it is strongly right-skewed
  // and a symmetric window truncates the tail that still carries mass. Widen the window as df
  // falls, and integrate the product on a fine panel grid: the integrand is dens(u) *
  // prange(q*u, k), and prange rises steeply in u when q is large, so the panels are doing
  // real work here — with 24 the df = 3 corner was off by 3e-6.
  const sd = 1 / Math.sqrt(2 * df);
  const lo = Math.max(0, 1 - 14 * sd - 0.6);
  const hi = 1 + 14 * sd + (df < 10 ? 3 : 0.8);

  const p = gl((u) => dens(u) * prange(q * u, k), lo, hi, 12);
  return p < 0 ? 0 : p > 1 ? 1 : p;
}

/** Upper tail — what a p-value actually is. */
export function ptukeyUpper(q: number, k: number, df: number): number {
  const p = 1 - ptukey(q, k, df);
  return p < 0 ? 0 : p > 1 ? 1 : p;
}

/**
 * Quantile of the studentized range: the critical value behind a Tukey / Games–Howell interval.
 *
 * Bisection, but on a BUDGET. Every probe evaluates a double integral, so the iteration count is
 * not free the way it is for a closed-form CDF — 200 iterations of a 1e-10 tolerance is how the
 * first version of this took 58 seconds to post-hoc thirty datasets. A confidence bound is
 * reported to a few decimals; 1e-7 is already far past what anyone reads.
 */
export function qtukey(p: number, k: number, df: number): number {
  if (!(p > 0) || !(p < 1)) return NaN;
  // BISECTION, deliberately. A secant looks like the obvious speed-up and is a trap here: the
  // bracket's upper end sits in the SATURATED tail, where ptukey(11.4) and ptukey(12) are both
  // 1.0 to machine precision. The secant's slope is then 0/0, it bails on the first step, and
  // it returns the bracket end — qtukey(.95, 3, 150) came back as 11.4 instead of 3.35, which
  // silently widened every Tukey confidence interval by a factor of three while leaving the
  // p-values (which do not use qtukey) exact. Bisection cannot do that.
  //
  // ~25 probes to 1e-6, which is far past what a reported CI bound shows.
  let lo = 0;
  let hi = 12;
  while (ptukey(hi, k, df) < p && hi < 1e3) hi *= 2;
  for (let i = 0; i < 60; i++) {
    const mid = (lo + hi) / 2;
    if (ptukey(mid, k, df) < p) lo = mid; else hi = mid;
    if (hi - lo < 1e-6) break;
  }
  return (lo + hi) / 2;
}
