/**
 * Group comparison, properly: descriptives, omnibus tests, post-hoc tests, effect sizes.
 *
 * Which post-hoc test is correct depends on assumptions the data has already broken or kept,
 * and offering only one is offering the wrong one half the time:
 *
 *   TUKEY HSD      — the classic. Assumes EQUAL VARIANCES and pools them into one MSE. Exact
 *                    familywise error under that assumption, and anticonservative without it.
 *   GAMES–HOWELL   — Tukey without the equal-variance assumption: each pair gets its own
 *                    standard error and its own Welch–Satterthwaite df. This is the right
 *                    default when cluster sizes and spreads differ, which for latent clusters
 *                    they almost always do.
 *   WELCH pairwise — pairwise t with unequal variances, corrected by p.adjust. Simpler and
 *                    more conservative than Games–Howell; no studentized range.
 *   DUNN           — the rank-based one. The post-hoc that actually belongs with a
 *                    Kruskal–Wallis omnibus, using the SAME pooled ranks and tie correction,
 *                    which is why running Mann–Whitney pairs instead is not the same test.
 *
 * Tukey and Games–Howell are both defined against the studentized range (`./ptukey.ts`);
 * substituting a t quantile silently discards the multiplicity correction they exist to make.
 */
import { ptukeyUpper, qtukey, pnorm } from './ptukey.js';
import { pf, pt2, anova, kruskal, type AnovaResult, type KruskalResult } from './group-tests.js';
import { pAdjust, type PAdjustMethod } from './pAdjust.js';

// ---------------------------------------------------------------------------
// Descriptives
// ---------------------------------------------------------------------------
export interface Describe {
  group: string;
  n: number;
  mean: number;
  sd: number;
  se: number;
  median: number;
  q1: number;
  q3: number;
  iqr: number;
  min: number;
  max: number;
  /** 95% CI of the MEAN (t-based) — not a range of the data. */
  ciLower: number;
  ciUpper: number;
}

/** R's `quantile(type = 7)` — the default, and the one every R answer you compare against uses. */
export function quantile7(sorted: readonly number[], p: number): number {
  const n = sorted.length;
  if (n === 0) return NaN;
  if (n === 1) return sorted[0]!;
  const h = (n - 1) * p;
  const lo = Math.floor(h);
  const hi = Math.min(lo + 1, n - 1);
  return sorted[lo]! + (h - lo) * (sorted[hi]! - sorted[lo]!);
}

/** Inverse t CDF by bisection — used only for CI bounds, a handful of calls. */
function qt(p: number, df: number): number {
  let lo = -100;
  let hi = 100;
  for (let i = 0; i < 200; i++) {
    const mid = (lo + hi) / 2;
    // two-sided pt2 gives P(|T| > |t|); convert to lower tail
    const cdf = mid >= 0 ? 1 - pt2(mid, df) / 2 : pt2(mid, df) / 2;
    if (cdf < p) lo = mid; else hi = mid;
    if (hi - lo < 1e-10) break;
  }
  return (lo + hi) / 2;
}

export function describeGroups(names: readonly string[], groups: readonly number[][]): Describe[] {
  return groups.map((g, i) => {
    const n = g.length;
    const s = g.slice().sort((a, b) => a - b);
    const mean = g.reduce((a, b) => a + b, 0) / (n || 1);
    const sd = n > 1
      ? Math.sqrt(g.reduce((a, v) => a + (v - mean) * (v - mean), 0) / (n - 1))
      : NaN;
    const se = n > 1 ? sd / Math.sqrt(n) : NaN;
    const tc = n > 1 ? qt(0.975, n - 1) : NaN;
    const q1 = quantile7(s, 0.25);
    const q3 = quantile7(s, 0.75);
    return {
      group: names[i]!, n, mean, sd, se,
      median: quantile7(s, 0.5), q1, q3, iqr: q3 - q1,
      min: s[0]!, max: s[n - 1]!,
      ciLower: n > 1 ? mean - tc * se : NaN,
      ciUpper: n > 1 ? mean + tc * se : NaN,
    };
  });
}

// ---------------------------------------------------------------------------
// Omnibus
// ---------------------------------------------------------------------------
export interface WelchAnovaResult { F: number; df1: number; df2: number; p: number }

/**
 * Welch's ANOVA — `oneway.test(var.equal = FALSE)`. The omnibus that does NOT assume equal
 * variances, and the one that belongs with Games–Howell.
 */
export function welchAnova(groups: readonly number[][]): WelchAnovaResult | null {
  const gs = groups.filter((g) => g.length > 1);
  const k = gs.length;
  if (k < 2) return null;

  const n = gs.map((g) => g.length);
  const m = gs.map((g) => g.reduce((a, b) => a + b, 0) / g.length);
  const v = gs.map((g, i) => g.reduce((a, x) => a + (x - m[i]!) * (x - m[i]!), 0) / (g.length - 1));
  if (v.some((x) => !(x > 0))) return null;                 // a constant group: no Welch F

  const w = n.map((ni, i) => ni / v[i]!);
  const sw = w.reduce((a, b) => a + b, 0);
  const mw = w.reduce((a, wi, i) => a + wi * m[i]!, 0) / sw;

  const A = w.reduce((a, wi, i) => a + wi * (m[i]! - mw) * (m[i]! - mw), 0) / (k - 1);
  const tmp = w.reduce((a, wi, i) => a + ((1 - wi / sw) * (1 - wi / sw)) / (n[i]! - 1), 0);
  const B = 1 + (2 * (k - 2) * tmp) / (k * k - 1);
  const F = A / B;
  const df2 = 1 / ((3 * tmp) / (k * k - 1));
  return { F, df1: k - 1, df2, p: pf(F, k - 1, df2) };
}

// ---------------------------------------------------------------------------
// Effect sizes
// ---------------------------------------------------------------------------
export interface EffectSizes {
  /** SS_between / SS_total. Biased upward — always reports SOME effect. */
  eta2: number;
  /** Bias-corrected. Can be negative, and that is information, not a bug. */
  omega2: number;
  /** Rank-based, for Kruskal–Wallis: H / (N - 1). `effectsize::rank_epsilon_squared`. */
  epsilon2: number | null;
}

export function effectSizes(groups: readonly number[][], _anova: AnovaResult | null, kw: KruskalResult | null): EffectSizes {
  const gs = groups.filter((g) => g.length > 0);
  const N = gs.reduce((s, g) => s + g.length, 0);
  const k = gs.length;
  const grand = gs.flat().reduce((s, v) => s + v, 0) / N;
  const ssB = gs.reduce((s, g) => {
    const m = g.reduce((a2, b) => a2 + b, 0) / g.length;
    return s + g.length * (m - grand) * (m - grand);
  }, 0);
  const ssT = gs.flat().reduce((s, v) => s + (v - grand) * (v - grand), 0);
  const ssW = ssT - ssB;
  const msW = ssW / (N - k);
  return {
    eta2: ssT > 0 ? ssB / ssT : NaN,
    omega2: ssT + msW > 0 ? (ssB - (k - 1) * msW) / (ssT + msW) : NaN,
    epsilon2: kw && N > 1 ? kw.H / (N - 1) : null,
  };
}

/**
 * Hedges' g — Cohen's d with the small-sample bias correction. Per PAIR.
 *
 * The correction factor is the EXACT one,
 *
 *   J(m) = Gamma(m/2) / ( sqrt(m/2) * Gamma((m-1)/2) ),   m = n1 + n2 - 2
 *
 * not the familiar `1 - 3/(4m - 1)` approximation. They agree to about 1e-4, which sounds
 * like nothing until you compare against `effectsize::hedges_g`, which uses the exact form:
 * the approximation showed up as a 1.6e-4 mismatch on the small-n datasets — precisely where
 * the correction is doing any work at all.
 */
export function hedgesG(x: readonly number[], y: readonly number[]): number {
  const n1 = x.length;
  const n2 = y.length;
  if (n1 < 2 || n2 < 2) return NaN;
  const m1 = x.reduce((a, b) => a + b, 0) / n1;
  const m2 = y.reduce((a, b) => a + b, 0) / n2;
  const v1 = x.reduce((a, v) => a + (v - m1) * (v - m1), 0) / (n1 - 1);
  const v2 = y.reduce((a, v) => a + (v - m2) * (v - m2), 0) / (n2 - 1);
  const sp = Math.sqrt(((n1 - 1) * v1 + (n2 - 1) * v2) / (n1 + n2 - 2));
  const d = sp > 0 ? (m1 - m2) / sp : NaN;
  const m = n1 + n2 - 2;
  const J = Math.exp(lgammaFn(m / 2) - 0.5 * Math.log(m / 2) - lgammaFn((m - 1) / 2));
  return d * J;
}

/** Lanczos log-gamma — needed for the exact Hedges correction. */
function lgammaFn(x: number): number {
  const g = 7;
  const c = [
    0.99999999999980993, 676.5203681218851, -1259.1392167224028, 771.32342877765313,
    -176.61502916214059, 12.507343278686905, -0.13857109526572012, 9.9843695780195716e-6,
    1.5056327351493116e-7,
  ];
  if (x < 0.5) return Math.log(Math.PI / Math.sin(Math.PI * x)) - lgammaFn(1 - x);
  const z = x - 1;
  let a = c[0]!;
  const t = z + g + 0.5;
  for (let i = 1; i < g + 2; i++) a += c[i]! / (z + i);
  return 0.5 * Math.log(2 * Math.PI) + (z + 0.5) * Math.log(t) - t + Math.log(a);
}

// ---------------------------------------------------------------------------
// Post-hoc
// ---------------------------------------------------------------------------
export interface PostHocPair {
  a: string;
  b: string;
  /** mean(b) − mean(a) — R's TukeyHSD orients "b-a" this way. */
  diff: number;
  /** The test statistic: q for Tukey/Games–Howell, t for Welch, z for Dunn. */
  statistic: number;
  df: number | null;
  p: number;
  pAdj: number;
  ciLower: number | null;
  ciUpper: number | null;
  /** Hedges' g for this pair — a p-value alone never says how big. */
  effect: number;
}

export type PostHocMethod = 'tukey' | 'gamesHowell' | 'welch' | 'dunn';

const pairsOf = <T,>(xs: readonly T[]): [number, number][] => {
  const out: [number, number][] = [];
  for (let i = 0; i < xs.length - 1; i++) for (let j = i + 1; j < xs.length; j++) out.push([i, j]);
  return out;
};

/**
 * Tukey's HSD — `TukeyHSD(aov(y ~ g))`.
 *
 * One pooled MSE across all groups, and the studentized range for the multiplicity. Exact
 * familywise alpha WHEN the variances are equal; anticonservative when they are not, which is
 * why Games–Howell exists.
 */
export function tukeyHSD(names: readonly string[], groups: readonly number[][], level = 0.05): PostHocPair[] {
  const N = groups.reduce((s, g) => s + g.length, 0);
  const k = groups.length;
  const dfErr = N - k;
  if (dfErr < 1) return [];
  const m = groups.map((g) => g.reduce((a, b) => a + b, 0) / g.length);
  const ssW = groups.reduce((s, g, i) => s + g.reduce((a, v) => a + (v - m[i]!) * (v - m[i]!), 0), 0);
  const mse = ssW / dfErr;
  const crit = qtukey(1 - level, k, dfErr);

  const raw = pairsOf(groups).map(([i, j]) => {
    const se = Math.sqrt((mse / 2) * (1 / groups[i]!.length + 1 / groups[j]!.length));
    const diff = m[j]! - m[i]!;
    const q = se > 0 ? Math.abs(diff) / se : NaN;
    return {
      a: names[i]!, b: names[j]!, diff, statistic: q, df: dfErr,
      p: ptukeyUpper(q, k, dfErr),
      ciLower: diff - crit * se, ciUpper: diff + crit * se,
      effect: hedgesG(groups[j]!, groups[i]!),
    };
  });
  // Tukey's p is ALREADY familywise — adjusting it again would correct twice.
  return raw.map((r) => ({ ...r, pAdj: r.p }));
}

/**
 * Games–Howell — `rstatix::games_howell_test`.
 *
 * Tukey's studentized range, but each pair gets its OWN standard error and its own
 * Welch–Satterthwaite df. No pooled MSE, no equal-variance assumption.
 */
export function gamesHowell(names: readonly string[], groups: readonly number[][], level = 0.05): PostHocPair[] {
  const k = groups.length;
  const n = groups.map((g) => g.length);
  const m = groups.map((g) => g.reduce((a, b) => a + b, 0) / g.length);
  const v = groups.map((g, i) => (g.length > 1
    ? g.reduce((a, x) => a + (x - m[i]!) * (x - m[i]!), 0) / (g.length - 1)
    : NaN));

  const raw = pairsOf(groups).map(([i, j]) => {
    const vi = v[i]! / n[i]!;
    const vj = v[j]! / n[j]!;
    const diff = m[j]! - m[i]!;
    // se of the DIFFERENCE, halved — the studentized range is defined on that scale
    const se = Math.sqrt((vi + vj) / 2);
    const q = se > 0 ? Math.abs(diff) / se : NaN;
    const df = ((vi + vj) * (vi + vj)) /
      ((vi * vi) / (n[i]! - 1) + (vj * vj) / (n[j]! - 1));   // Welch–Satterthwaite
    const crit = qtukey(1 - level, k, df);
    return {
      a: names[i]!, b: names[j]!, diff, statistic: q, df,
      p: ptukeyUpper(q, k, df),
      ciLower: diff - crit * se, ciUpper: diff + crit * se,
      effect: hedgesG(groups[j]!, groups[i]!),
    };
  });
  return raw.map((r) => ({ ...r, pAdj: r.p }));   // familywise by construction, as Tukey
}

/** Pairwise Welch t, then p.adjust. Simpler than Games–Howell and more conservative. */
export function welchPairs(
  names: readonly string[], groups: readonly number[][], adjust: PAdjustMethod = 'holm',
): PostHocPair[] {
  const raw = pairsOf(groups).map(([i, j]) => {
    const x = groups[i]!;
    const y = groups[j]!;
    const n1 = x.length;
    const n2 = y.length;
    const m1 = x.reduce((a, b) => a + b, 0) / n1;
    const m2 = y.reduce((a, b) => a + b, 0) / n2;
    const v1 = x.reduce((a, v) => a + (v - m1) * (v - m1), 0) / (n1 - 1);
    const v2 = y.reduce((a, v) => a + (v - m2) * (v - m2), 0) / (n2 - 1);
    const se2 = v1 / n1 + v2 / n2;
    const se = Math.sqrt(se2);
    const t = se > 0 ? (m2 - m1) / se : NaN;
    const df = (se2 * se2) / ((v1 / n1) ** 2 / (n1 - 1) + (v2 / n2) ** 2 / (n2 - 1));
    const tc = qt(1 - 0.05 / 2, df);
    return {
      a: names[i]!, b: names[j]!, diff: m2 - m1, statistic: t, df,
      p: pt2(t, df),
      ciLower: (m2 - m1) - tc * se, ciUpper: (m2 - m1) + tc * se,
      effect: hedgesG(y, x),
    };
  });
  const adj = Array.from(pAdjust(raw.map((r) => r.p), adjust));
  return raw.map((r, i) => ({ ...r, pAdj: adj[i]! }));
}

/**
 * Dunn's test — the post-hoc that belongs with Kruskal–Wallis.
 *
 * It re-uses the SAME pooled ranks and the SAME tie correction as the omnibus, which is the
 * whole point: running pairwise Mann–Whitney tests instead re-ranks within each pair and is
 * therefore a different test that can disagree with the omnibus it is supposed to follow.
 */
export function dunnTest(
  names: readonly string[], groups: readonly number[][], adjust: PAdjustMethod = 'holm',
): PostHocPair[] {
  const flat: { v: number; g: number }[] = [];
  groups.forEach((g, i) => g.forEach((v) => flat.push({ v, g: i })));
  const N = flat.length;
  if (N < 3) return [];

  // midranks over the POOLED sample
  flat.sort((a, b) => a.v - b.v);
  const rank = new Array<number>(N);
  const tieGroups: number[] = [];
  let i = 0;
  while (i < N) {
    let j = i;
    while (j + 1 < N && flat[j + 1]!.v === flat[i]!.v) j++;
    const r = (i + j + 2) / 2;                       // 1-indexed midrank
    for (let t = i; t <= j; t++) rank[t] = r;
    if (j > i) tieGroups.push(j - i + 1);
    i = j + 1;
  }

  const n = groups.map((g) => g.length);
  const rsum = new Array<number>(groups.length).fill(0);
  flat.forEach((e, idx) => { rsum[e.g]! += rank[idx]!; });
  const rbar = rsum.map((s, g) => s / n[g]!);

  // the tie correction — the same one Kruskal–Wallis applies
  const tieSum = tieGroups.reduce((s, t) => s + (t * t * t - t), 0);
  const sigma2 = (N * (N + 1)) / 12 - tieSum / (12 * (N - 1));

  const raw = pairsOf(groups).map(([a, b]) => {
    const se = Math.sqrt(sigma2 * (1 / n[a]! + 1 / n[b]!));
    const z = se > 0 ? (rbar[b]! - rbar[a]!) / se : NaN;
    return {
      a: names[a]!, b: names[b]!,
      diff: rbar[b]! - rbar[a]!,                     // difference in MEAN RANK, not in means
      statistic: z, df: null,
      p: 2 * (1 - pnorm(Math.abs(z))),
      ciLower: null, ciUpper: null,
      effect: hedgesG(groups[b]!, groups[a]!),
    };
  });
  const adj = Array.from(pAdjust(raw.map((r) => r.p), adjust));
  return raw.map((r, idx) => ({ ...r, pAdj: adj[idx]! }));
}

export function postHoc(
  method: PostHocMethod, names: readonly string[], groups: readonly number[][],
  adjust: PAdjustMethod = 'holm', level = 0.05,
): PostHocPair[] {
  switch (method) {
    case 'tukey': return tukeyHSD(names, groups, level);
    case 'gamesHowell': return gamesHowell(names, groups, level);
    case 'dunn': return dunnTest(names, groups, adjust);
    default: return welchPairs(names, groups, adjust);
  }
}

// ---------------------------------------------------------------------------
// A whole numeric covariate, end to end
// ---------------------------------------------------------------------------
export interface OmnibusChoice { anova: AnovaResult | null; welch: WelchAnovaResult | null; kruskal: KruskalResult | null }

export interface CovariateReport {
  covariate: string;
  describe: Describe[];
  omnibus: OmnibusChoice;
  effects: EffectSizes;
  postHoc: PostHocPair[];
  method: PostHocMethod;
  /** True when the group variances differ enough that the pooled-variance tests are suspect. */
  heteroscedastic: boolean;
}

/** Levene's test (Brown–Forsythe, median-centred) — is the equal-variance assumption safe? */
export function leveneBF(groups: readonly number[][]): { F: number; df1: number; df2: number; p: number } | null {
  const gs = groups.filter((g) => g.length > 1);
  const k = gs.length;
  if (k < 2) return null;
  const z = gs.map((g) => {
    const s = g.slice().sort((a, b) => a - b);
    const med = quantile7(s, 0.5);
    return g.map((v) => Math.abs(v - med));
  });
  const a = anova(z);
  return a ? { F: a.F, df1: a.df1, df2: a.df2, p: a.p } : null;
}

export function analyseCovariate(
  covariate: string, names: readonly string[], groups: readonly number[][],
  options?: { method?: PostHocMethod | 'auto'; adjust?: PAdjustMethod; level?: number },
): CovariateReport {
  const adjust = options?.adjust ?? 'holm';
  const level = options?.level ?? 0.05;
  const gs = groups.map((g) => g.slice());
  const a = anova(gs);
  const w = welchAnova(gs);
  const kw = kruskal(gs);
  const lev = leveneBF(gs);
  // "Suspect" = Levene rejects at .05. Not a hard switch — it picks the DEFAULT, and the
  // caller can always override. Silently pooling variances that differ is the failure mode
  // this exists to avoid.
  const hetero = !!lev && lev.p < 0.05;

  let method = options?.method ?? 'auto';
  if (method === 'auto') method = hetero ? 'gamesHowell' : 'tukey';

  return {
    covariate,
    describe: describeGroups(names, groups),
    omnibus: { anova: a, welch: w, kruskal: kw },
    effects: effectSizes(gs, a, kw),
    postHoc: postHoc(method, names, groups, adjust, level),
    method,
    heteroscedastic: hetero,
  };
}
